<?php
namespace Tests\Unit;
use App\Modules\Products\Models\{Product,ProductAttribute,ProductCategory,ProductCollection,ProductVariant}; use Illuminate\Database\Eloquent\Relations\BelongsToMany; use PHPUnit\Framework\TestCase;
class ProductsModuleArchitectureTest extends TestCase { public function test_product_models_are_tenant_scoped_and_variants_use_flexible_attributes(): void { foreach([new Product,new ProductCategory,new ProductCollection,new ProductAttribute,new ProductVariant] as $model)$this->assertSame('tenant',$model->getConnectionName()); $this->assertInstanceOf(BelongsToMany::class,(new ProductVariant)->attributeValues()); } public function test_product_migration_is_incremental_and_does_not_embed_contifico_import_rules(): void { $migration=file_get_contents(database_path('migrations/tenant/2026_08_31_001100_create_products_module.php')); $this->assertStringContainsString('product_variant_attribute_value',$migration); $this->assertStringNotContainsString('Contífico',$migration); } }
